class Solution {
    int m, n;
    vector<vector<int>>* g;
    vector<vector<long long>> memo;
    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};
public:
    long long dfs(int r, int c) {
        if (memo[r][c] != -1) return memo[r][c];
        long long res = 1;
        for (int d = 0; d < 4; d++) {
            int nr = r + dr[d];
            int nc = c + dc[d];
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && (*g)[nr][nc] > (*g)[r][c]) {
                res = (res + dfs(nr, nc)) % 1000000007;
            }
        }
        memo[r][c] = res;
        return res;
    }

    int countPaths(vector<vector<int>>& grid) {
        m = grid.size();
        n = grid[0].size();
        g = &grid;
        memo.assign(m, vector<long long>(n, -1));
        long long total = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                total = (total + dfs(i, j)) % 1000000007;
            }
        }
        return (int)total;
    }
};
